#!/bin/sh
# Put the Neo Geo CD's art and audio into the Android app's assets folder.
#   - calm.pak: every picture (make_pak.py)
#   - sfx/*.wav: the 16 sound effects, as they are
#   - music/track1..3.ogg: the three scene songs.  Your own WAVs in
#     neogeo-cd/src/assets/cdda/ are used; missing ones are generated by
#     neogeo-cd/tools/make_audio.py, exactly as for the disc.
# Needs python3 with pillow, numpy, scipy, and ffmpeg.
set -e
cd "$(dirname "$0")/../.."
OUT=android/app/src/main/assets
mkdir -p "$OUT/sfx" "$OUT/music"
python3 android/tools/make_pak.py "$OUT/calm.pak"
cp neogeo-cd/src/assets/sfx/*.wav "$OUT/sfx/"
python3 neogeo-cd/tools/make_audio.py
n=1
for t in track02_lakeside track03_shoreline track04_rain; do
    ffmpeg -v error -y -i "neogeo-cd/src/assets/cdda/$t.wav" -c:a libvorbis -q:a 4 "$OUT/music/track$n.ogg"
    n=$((n + 1))
done
ls -l "$OUT" "$OUT/music"
